    fun getPrixParCC(): Double {
        val produits = allProducts.filter { it.cc > 0 }
        if (produits.isEmpty()) return 0.0
        return produits.sumOf { it.prixPublic.toDouble() / it.cc } / produits.size
    }

    fun getByPathologie(pathologie: String): List<Product> {
        return allProducts.filter { product ->
            product.pathologies.any { it.contains(pathologie, ignoreCase = true) }
        }
    }
